625		}
626		// 结束后不再派发
627		if _, err := s.Claim(spec.ID, "d2", upBase.Add(2*time.Hour+time.Minute)); !errors.Is(err, ErrCampaignEnded) {
628			t.Fatalf("claim after end: %v", err)
