630		// 结束后的新结果报错
631		if err := s.SubmitResult(OperationResult{
632			CampaignID: spec.ID, DeviceID: "d2", OperationID: dl2.ID,
633			At: upBase.Add(2*time.Hour + time.Minute), Success: true,
634		}); !errors.Is(err, ErrCampaignEnded) {
635			t.Fatalf("new result after end: %v", err)
636		}
637		// 已接受结果的重复提交在结束后仍有效（用 d1 的安装结果重放）
638		d1 := findDevice(v, "d1")
639		if err := s.SubmitResult(OperationResult{
640			CampaignID: spec.ID, DeviceID: "d1", OperationID: d1.InstallID,
641			At: upBase.Add(3 * time.Hour), Success: true,
642			Seq: 2, Version: "v2", Config: json.RawMessage(`{"ok":true}`),
643		}); err != nil {
644			t.Fatalf("duplicate after end: %v", err)
645		}
646		v2, _ := s.GetCampaign(spec.ID)
647		if len(v2.Results) != len(v.Results) {
648			t.Fatal("replay after end added history")
649		}
650	}
